import java.util.*;

class TreeCodec {
    public TreeCodec() {}

    public String encode(TreeNode root) {
        StringBuilder sb = new StringBuilder();
        write(root, sb);
        return sb.toString();
    }

    private void write(TreeNode n, StringBuilder sb) {
        if (sb.length() > 0) sb.append(',');
        if (n == null) { sb.append('#'); return; }  // marker for a missing child
        sb.append(n.val);
        write(n.left, sb);
        write(n.right, sb);
    }

    private String[] tok;
    private int pos;

    public TreeNode decode(String data) {
        tok = data.split(",");
        pos = 0;
        return read();
    }

    private TreeNode read() {
        String t = tok[pos++];
        if (t.equals("#")) return null;
        TreeNode n = new TreeNode(Integer.parseInt(t));
        n.left = read();   // tokens are in pre-order: node, left, right
        n.right = read();
        return n;
    }
}

