class TreeCodec:
    def encode(self, root: Optional[TreeNode]) -> str:
        out = []
        def go(n):
            if not n: out.append("#"); return
            out.append(str(n.val)); go(n.left); go(n.right)
        go(root)
        return ",".join(out)
    def decode(self, data: str) -> Optional[TreeNode]:
        it = iter(data.split(","))
        def go():
            t = next(it)
            if t == "#": return None
            n = TreeNode(int(t)); n.left = go(); n.right = go()
            return n
        return go()

